\begin{align*}
&\left(\frac{1}{2}\cdot \frac{10}{3}\cdot \frac{40}{17}\right)+\left(\frac{1}{2}\cdot \frac{10}{3}\cdot 2\cdot \frac{40}{17}\right)+\cdots+\left(\frac{1}{2}\cdot \frac{10}{3}\cdot 17\cdot \frac{40}{17}\right)\\
&= \frac{1}{2}\cdot \frac{10}{3}\cdot \frac{40}{17}\left(1+2+3+\cdots+17\right)\\
&= \frac{1}{2}\cdot \frac{10}{3}\cdot \frac{40}{17}\cdot 17\cdot 9\\
&=\boxed{600}
\end{align*}

